const people = $json.people || [];
const taxonomy = `Categories (pick exactly one per person):
- automation-heavy: n8n, zapier, langchain, selenium, web scraping dominate (>=2 automation tools wins)
- web-dev: react / javascript front-end dominates
- backend: fastapi, rest apis, docker, python server work dominates
- data: sql, mysql, mongodb, pandas dominate
- mixed: real skills but no clear majority
- unknown: no skill information at all`;

const payload = people.map(p => ({
  person_id: p.person_id,
  full_name: p.full_name,
  city: p.city,
  experience_years: p.experience_years,
  naukri_skills: p.naukri_skills,
  gig_skills: p.gig_skills
}));

const prompt = `${taxonomy}\n\nClassify each person. Return ONLY a JSON array (no markdown) of objects:\n[{ "person_id": number, "skill_category": string, "confidence": number between 0 and 1 }]\n\nPeople:\n${JSON.stringify(payload, null, 2)}`;

return [{ json: { prompt, batch_size: people.length } }];

const VALID = new Set(['automation-heavy','web-dev','backend','data','mixed','unknown']);
const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text || '[]';
let parsed;
try {
  parsed = JSON.parse(raw.replace(/^```json\s*|\s*```$/g, '').trim());
} catch (e) {
  return [{ json: { error: 'gemini_parse_failed', raw, valid: [], invalid: [] } }];
}
if (!Array.isArray(parsed)) parsed = [parsed];
const valid = [];
const invalid = [];
for (const row of parsed) {
  const cat = String(row.skill_category || '').trim().toLowerCase();
  const pid = Number(row.person_id);
  const conf = Number(row.confidence);
  if (!Number.isInteger(pid) || !VALID.has(cat)) {
    invalid.push(row);
    continue;
  }
  valid.push({
    person_id: pid,
    skill_category: cat,
    confidence: Number.isFinite(conf) ? Math.min(1, Math.max(0, conf)) : 0.5
  });
}
return [{ json: { valid, invalid, skipped: invalid.length } }];

const write = $('Write Tags').item?.json || {};
const validate = $('Validate Categories').item.json;
return [{ json: {
  ok: true,
  updated: write.updated ?? 0,
  skipped_api: write.skipped || [],
  invalid_llm: validate.invalid || [],
  message: 'Batch tagged. Re-trigger webhook to process next batch of 15.'
}}];

const v = $json;
return [{ json: {
  ok: false,
  alert: 'no_valid_tags',
  invalid_llm: v.invalid || [],
  error: v.error || null,
  message: 'Gemini returned no valid categories — nothing written.'
}}];
